def allow_cancel(age_seconds, until_start_seconds):
    # 10분은 600초입니다.
    grace_period = 600

    # 예약 생성 후 10분이 지났는지 확인합니다.
    if age_seconds <= grace_period:
        return True

    # 이용 시작 24시간 전까지만 취소를 허용합니다.
    if until_start_seconds > 86400:
        return True

    return False
